import re
from collections import Counter

STOP = {"the", "a", "of", "and"}

def top_words(text, n=5):
    # lowercase first, otherwise "The" and "the" split the count
    words = re.findall(r"[a-z']+", text.lower())
    counts = Counter(w for w in words if w not in STOP)
    return counts.most_common(n)

def load(path):
    with open(path, encoding="utf-8") as fh:
        return fh.read()

if __name__ == "__main__":
    import sys
    print(top_words(load(sys.argv[1])))

import os
import sys

def load_config(path):
    # Open the file and read it
    with open(path) as f:
        text = f.read()
    cfg = {}
    for line in text.splitlines():
        if "=" not in line:
            continue
        k, v = line.split("=", 1)
        cfg[k.strip()] = v.strip()
    # windows paths come through with a trailing \r on some machines
    return cfg

def main():
    cfg = load_config(sys.argv[1])
    # Print the configuration
    for k in cfg:
        print(k, cfg[k])

main()
